-- W31-09 — Web Push subscriptions (VAPID), transporte opcional.
-- Sem VAPID_PUBLIC_KEY/VAPID_PRIVATE_KEY no .env, o push fica desativado
-- (fail-closed) — as inscrições seguem armazenadas para quando a ops ligar.

CREATE TABLE "PushSubscriptions"(
    "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "id_usuario" BIGINT NOT NULL,
    "endpoint" VARCHAR(512) NOT NULL,
    "p256dh" VARCHAR(255) NOT NULL,
    "auth" VARCHAR(255) NOT NULL,
    "user_agent" VARCHAR(255) NULL,
    "criado_em" TIMESTAMP NOT NULL DEFAULT NOW(),
    "atualizado_em" TIMESTAMP NOT NULL DEFAULT NOW(),
    CONSTRAINT "uq_push_subscription_user_endpoint" UNIQUE ("id_usuario", "endpoint")
);

CREATE INDEX "idx_push_subscription_endpoint" ON "PushSubscriptions"("endpoint");

ALTER TABLE "PushSubscriptions"
  ADD CONSTRAINT "fk_push_subscription_usuario"
  FOREIGN KEY ("id_usuario") REFERENCES "Usuarios"("id") ON DELETE CASCADE;